CREATE TABLE admins (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, password_salt TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner', 'admin')), created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE invitations (id TEXT PRIMARY KEY, token_hash TEXT UNIQUE NOT NULL, expires_at DATETIME NOT NULL, created_by TEXT NOT NULL, used_at DATETIME, FOREIGN KEY (created_by) REFERENCES admins(id));
CREATE TABLE sessions (id TEXT PRIMARY KEY, admin_id TEXT NOT NULL, expires_at DATETIME NOT NULL, user_agent TEXT, FOREIGN KEY (admin_id) REFERENCES admins(id) ON DELETE CASCADE);
CREATE TABLE levels (id TEXT PRIMARY KEY, name TEXT UNIQUE NOT NULL);
CREATE TABLE semesters (id TEXT PRIMARY KEY, name TEXT UNIQUE NOT NULL);
CREATE TABLE courses (id TEXT PRIMARY KEY, code TEXT UNIQUE NOT NULL, title TEXT NOT NULL, level_id TEXT NOT NULL, semester_id TEXT NOT NULL, is_approved BOOLEAN DEFAULT 0, FOREIGN KEY (level_id) REFERENCES levels(id), FOREIGN KEY (semester_id) REFERENCES semesters(id));
CREATE TABLE tags (id TEXT PRIMARY KEY, name TEXT UNIQUE NOT NULL, is_approved BOOLEAN DEFAULT 0);
CREATE TABLE submissions (id TEXT PRIMARY KEY, ticket_number TEXT UNIQUE NOT NULL, secret_hash TEXT NOT NULL, contributor_name TEXT NOT NULL, course_id TEXT, title TEXT NOT NULL, type TEXT NOT NULL, description TEXT, original_filename TEXT NOT NULL, mime_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, file_hash TEXT NOT NULL, duplicate_warning BOOLEAN DEFAULT 0, possible_duplicate_of TEXT, status TEXT NOT NULL CHECK(status IN ('pending', 'approved', 'rejected')), rejection_reason TEXT, r2_original_key TEXT NOT NULL, r2_compressed_key TEXT, lock_admin_id TEXT, lock_expires_at DATETIME, version INTEGER DEFAULT 1, cleanup_at DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (course_id) REFERENCES courses(id), FOREIGN KEY (lock_admin_id) REFERENCES admins(id));
CREATE TABLE submission_tags (submission_id TEXT NOT NULL, tag_id TEXT NOT NULL, PRIMARY KEY (submission_id, tag_id), FOREIGN KEY (submission_id) REFERENCES submissions(id) ON DELETE CASCADE, FOREIGN KEY (tag_id) REFERENCES tags(id) ON DELETE CASCADE);
CREATE TABLE materials (id TEXT PRIMARY KEY, submission_id TEXT UNIQUE NOT NULL, course_id TEXT NOT NULL, contributor_name TEXT NOT NULL, title TEXT NOT NULL, type TEXT NOT NULL, size_bytes INTEGER NOT NULL, r2_object_key TEXT NOT NULL, is_pinned BOOLEAN DEFAULT 0, published_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (submission_id) REFERENCES submissions(id), FOREIGN KEY (course_id) REFERENCES courses(id));
CREATE TABLE material_tags (material_id TEXT NOT NULL, tag_id TEXT NOT NULL, PRIMARY KEY (material_id, tag_id), FOREIGN KEY (material_id) REFERENCES materials(id) ON DELETE CASCADE, FOREIGN KEY (tag_id) REFERENCES tags(id) ON DELETE CASCADE);
CREATE TABLE course_tag_suggestions (id TEXT PRIMARY KEY, type TEXT NOT NULL CHECK(type IN ('course', 'tag')), suggested_name TEXT NOT NULL, suggested_code TEXT, level_id TEXT, semester_id TEXT, status TEXT NOT NULL CHECK(status IN ('pending', 'approved', 'rejected')), reviewed_by TEXT, reviewed_at DATETIME, FOREIGN KEY (level_id) REFERENCES levels(id), FOREIGN KEY (semester_id) REFERENCES semesters(id), FOREIGN KEY (reviewed_by) REFERENCES admins(id));
CREATE TABLE activity_log (id TEXT PRIMARY KEY, admin_id TEXT NOT NULL, action TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT NOT NULL, details TEXT, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (admin_id) REFERENCES admins(id));
CREATE TABLE download_counts (id TEXT PRIMARY KEY, material_id TEXT NOT NULL, date TEXT NOT NULL, count INTEGER DEFAULT 1, UNIQUE(material_id, date), FOREIGN KEY (material_id) REFERENCES materials(id) ON DELETE CASCADE);
CREATE VIRTUAL TABLE search_index USING fts5(title, course_code, course_title, contributor_name, material_id UNINDEXED);
